  "medium": "Encaustic on wood",
  "text": "The Mother of God sits enthroned with the Christ Child on her lap. Two soldier saints stand guard in court dress, usually identified as Theodore and George, and behind them two angels lift their eyes toward the hand of God descending in a shaft of light.\n\nThe icon mixes styles on purpose. The saints are frontal and still, the angels painted in a looser, classical manner, and the Virgin's eyes turn aside. It is one of the earliest images of the Theotokos to survive.",
