  "school": "Novgorod",
  "artist": "",
  "origin": {
   "name": "Kirillo-Belozersky Monastery",
   "lat": 59.8584,
   "lng": 38.377
  },
  "originShort": "Kirillo-Belozersky Monastery",
  "home": {
   "name": "State Russian Museum",
   "lat": 59.9387,
   "lng": 30.3323,
   "city": "St Petersburg"
  },
  "medium": "Tempera on wood",
  "text": "Christ stands before the tomb in the rock, and Lazarus, four days dead, emerges bound in grave cloths. Martha and Mary fall at the Lord's feet, and a young man holds his nose against the smell, a detail the painters kept because the Gospel insists on it.\n\nLazarus Saturday, the day before Palm Sunday, is the only Saturday of the year when the Resurrection is celebrated as on a Sunday. It is a foretaste of Pascha.",
  "image": "assets/icons/raising-lazarus.jpg",
  "thumb": "assets/icons/raising-lazarus-thumb.jpg",
