  "medium": "Tempera on wood",
  "text": "Ohrid in North Macedonia keeps one of the richest collections of Byzantine icons outside Sinai, many of them brought or commissioned under the Palaiologan emperors.\n\nGabriel strides toward the Virgin, his cloak still billowing from flight, while she rises from her seat, a skein of purple wool in her hand. The wool is from the veil of the Temple, which tradition says she was spinning when the angel came.",
