  "medium": "Tempera on wood",
  "text": "These four scenes were once painted on the leaves of a pair of doors, perhaps from a small iconostasis or a cabinet for relics. At top left St John dictates his Gospel to his disciple Prochoros on the island of Patmos, his head turned to listen to the voice of God.\n\nThe Metropolitan Museum releases its images of works in the public domain under CC0, and they can be reused freely.",
