  "home": {
   "name": "Private collection",
   "lat": null,
   "lng": null,
   "city": ""
  },
  "medium": "Tempera on wood",
  "text": "James, called 'the Just', led the Church of Jerusalem after the Ascension and presided at the Apostolic Council (Acts 15). Tradition gives him the oldest surviving liturgy, still served on his feast in some places.\n\nThe tall, narrow format shows that this panel came from a row of saints in an iconostasis. He wears a bishop's vestments and holds the Gospel.",
