  "medium": "Tempera on wood",
  "text": "Empress Helena found the cross of Christ in Jerusalem around 326, and the bishop raised it before the crowd while the people cried 'Lord, have mercy'. In the icon he lifts it from the ambo of a great church, while Constantine and Helena stand by.\n\nThe village of Palekh, east of Moscow, was famous for its icon painters, who worked in a minute, jewel-like style. After 1917 they turned their skills to lacquer boxes.",
