  "medium": "Tempera on wood",
  "text": "In the tenth century St Andrew the Fool-for-Christ saw the Mother of God in the Blachernae church of Constantinople, spreading her veil over the people in prayer. The Russian Church made the vision a great feast, Pokrov, on 1 October.\n\nAs in most Russian versions, St Romanos the Melodist stands singing on the ambo below, because his memory falls on the same day.",
