  "medium": "Tempera and gold on wood",
  "text": "Sabbas (439–532) founded the Great Lavra in the Judean wilderness, which still stands above the Kidron valley. Its rule of services became the basis of the Orthodox Typikon.\n\nThe Cretan painter Philotheos Skoufos shows his burial, with his monks gathered around the bier among the cliffs of the desert.",
