  "text": "Theodore was a general (stratelates) at Heraclea who smashed the gold and silver idols of the city and gave the pieces to the poor. He was tortured and crucified under Licinius.\n\nThis vita icon comes from the Novgorod church dedicated to him, the Church of St Theodore Stratelates on the Brook.",
